SELECT CASE WHEN count(*) > 0 THEN 1 ELSE 0 END AS existence
FROM bt_a2a_platform
WHERE status_cd = '00A'
  AND tenant_id = #{tenantId}
  AND platform_code = #{platformCode}

SELECT CASE WHEN count(*) > 0 THEN 1 ELSE 0 END AS existence
FROM bt_a2a_agent
WHERE status_cd = '00A'
  AND tenant_id = #{tenantId}
  AND platform_id = #{platformId}

