  AND tenant_id = #{tenantId}
  AND platform_id = #{platformId}

SELECT platform_id, platform_name, platform_code, publish_key
FROM bt_a2a_platform
WHERE status_cd = '00A'
  AND tenant_id = #{tenantId}
  AND platform_code = #{platformCode}

SELECT auth_ext_func_id
FROM bt_a2a_platform
WHERE status_cd = '00A'
  AND tenant_id = #{tenantId}
  AND platform_id = #{platformId}

