mapper.select:
SELECT platform_id, platform_name, platform_code, platform_icon
FROM bt_a2a_platform
WHERE status_cd = '00A'
  AND tenant_id = #{query.tenantId}

  AND (
    platform_name LIKE #{query.searchContent}
    OR
    platform_code LIKE #{query.searchContent}
  )

ORDER BY updated_time DESC

SELECT a.platform_id, a.platform_name, a.platform_code, a.platform_desc, a.platform_icon, a.updated_time,
       b.real_name AS updator_name
FROM bt_a2a_platform a
LEFT JOIN bt_user b ON b.user_id = a.updator_id
WHERE a.status_cd = '00A'
  AND a.tenant_id = #{query.tenantId}

  AND (
    a.platform_name LIKE #{query.searchContent}
    OR
    a.platform_code LIKE #{query.searchContent}
  )

ORDER BY a.updated_time DESC
